-- Imported October 2026 DMR figures per BMC and period (the BMC's own litres, fat litres and SNF litres).
create table if not exists public.dmr_history (
  id bigint generated always as identity primary key,
  dairy_unit_id bigint not null references public.dairy_units (id),
  period_from date not null,
  period_to date not null,
  bmc_code integer not null,
  qty numeric(14,3) not null,
  fat_lit numeric(14,3) not null,
  snf_lit numeric(14,3) not null,
  created_at timestamptz not null default now(),
  unique (dairy_unit_id, period_from, bmc_code)
);
alter table public.dmr_history enable row level security; -- backend (service role) only

on conflict (dairy_unit_id, period_from, bmc_code) do nothing;
